import{St as e,at as t,it as n,o as r,ot as i,st as a,tt as o,vt as s}from"./chunks/framework.DQt_9H6f.js";var c=JSON.parse(`{"title":"File management","description":"","frontmatter":{},"headers":[],"relativePath":"guide/file-management.md","filePath":"guide/file-management.md"}`),l={name:`guide/file-management.md`};function u(r,c,l,u,d,f){let p=e(`FeatureCards`),m=e(`wa-icon`),h=e(`FileSelectHero`);return s(),n(`div`,null,[c[17]||=o(`h1`,{id:`file-management`,tabindex:`-1`},[i(`File management `),o(`a`,{class:`header-anchor`,href:`#file-management`,"aria-label":`Permalink to “File management”`},`​`)],-1),c[18]||=o(`p`,null,`This guide explains how TeXRA organizes input files, read-only context, media attachments, and run-storage outputs.`,-1),c[19]||=o(`h2`,{id:`file-categories`,tabindex:`-1`},[i(`File categories `),o(`a`,{class:`header-anchor`,href:`#file-categories`,"aria-label":`Permalink to “File categories”`},`​`)],-1),c[20]||=o(`p`,null,`TeXRA groups files into three categories:`,-1),a(p,{min:`220px`,cards:[{icon:`file-code`,title:`Input`,tag:`Read + edit`,tagVariant:`success`,desc:`Primary documents a program reads and rewrites.`,chips:[{text:`.tex`,variant:`accent`},{text:`.txt`,variant:`accent`},{text:`.md`,variant:`accent`}]},{icon:`book`,title:`Context`,tag:`Read-only`,tagVariant:`info`,desc:`Reference material a program sees but never modifies.`,chips:[{text:`.bib`,variant:`info`},{text:`.bbl`,variant:`info`},{text:`.sty`,variant:`info`},{text:`.cls`,variant:`info`},{text:`reference papers`,variant:`neutral`}]},{icon:`video`,title:`Media`,tag:`Visual / audio`,tagVariant:`neutral`,desc:`Figures and recordings handed to vision/audio models.`,chips:[{text:`images`,variant:`neutral`},{text:`PDF figures`,variant:`neutral`},{text:`audio`,variant:`neutral`}]}]}),c[21]||=t(`<p class="hero-caption">Three categories: Input is read + edited, Context is read-only, Media carries visual and audio content.</p><p>Input and Context belong to a <a href="./programs.html">program</a> run: the files it revises and the files it only reads. The assistant reads project files with its own tools, so a chat takes only Media attachments.</p><p>Read the <a href="./working-with-figures.html">Working with figures</a> guide for supported media formats and automatic figure extraction.</p><h3 id="pasting-images-from-the-clipboard" tabindex="-1">Pasting images from the clipboard <a class="header-anchor" href="#pasting-images-from-the-clipboard" aria-label="Permalink to “Pasting images from the clipboard”">​</a></h3><p>Paste an image (<code>Ctrl/Cmd+V</code>) into the instruction box to save it to workspace storage as <code>[pasted_&lt;timestamp&gt;_&lt;rand&gt;.ext]</code> and add it to the <strong>Media</strong> list automatically. If the selected model does not support vision, TeXRA warns you before running. Pasted images are cleaned up after 3 days.</p><h2 id="file-selection-interface" tabindex="-1">File selection interface <a class="header-anchor" href="#file-selection-interface" aria-label="Permalink to “File selection interface”">​</a></h2>`,6),o(`p`,null,[c[0]||=i(`When an agent proposes a program run, the proposal card lists the files it chose. Select `,-1),c[1]||=o(`strong`,null,`Edit`,-1),c[2]||=i(` on the card to change them: the launch form opens with a `,-1),c[3]||=o(`strong`,null,`Documents and attachments`,-1),c[4]||=i(` section for each file category (Input `,-1),a(m,{library:`texra`,name:`file-code`}),c[5]||=i(`, Context `,-1),a(m,{library:`texra`,name:`book`}),c[6]||=i(`, Media `,-1),a(m,{library:`texra`,name:`video`}),c[7]||=i(`):`,-1)]),a(h),c[22]||=o(`p`,{class:`hero-caption`},`Each category holds an ordered list of files with three quick actions in the header.`,-1),c[23]||=o(`h3`,{id:`file-list-controls`,tabindex:`-1`},[i(`File list controls `),o(`a`,{class:`header-anchor`,href:`#file-list-controls`,"aria-label":`Permalink to “File list controls”`},`​`)],-1),c[24]||=o(`p`,null,`Each category (Input, Context, and Media) manages a list of files; a single-file workflow is a list of length one. The header has three buttons:`,-1),o(`ul`,null,[o(`li`,null,[c[8]||=o(`strong`,null,`Add opened files`,-1),c[9]||=i(` (`,-1),a(m,{library:`texra`,name:`folder-open`}),c[10]||=i(`): Append every editor tab whose extension matches the category to the list.`,-1)]),o(`li`,null,[c[11]||=o(`strong`,null,`Clear all files`,-1),c[12]||=i(` (`,-1),a(m,{library:`texra`,name:`trash`}),c[13]||=i(`): Empty the list.`,-1)]),o(`li`,null,[c[14]||=o(`strong`,null,`Add files`,-1),c[15]||=i(` (`,-1),a(m,{library:`texra`,name:`plus`}),c[16]||=i(`): Open a file picker to append files.`,-1)])]),c[25]||=t(`<p>You can also <strong>drag and drop files</strong> from the OS file manager (or from VS Code&#39;s Explorer) onto a category to add them.</p><p>Inside the list:</p><ul><li>Each file row has a small trash icon to remove that file.</li><li>Drag a row to reorder files. Input files are sent to the program in this order.</li></ul><p>The list is the only mode; there is no separate &quot;single file&quot; view. To work with one file, keep the list at length one.</p><h3 id="output-files" tabindex="-1">Output files <a class="header-anchor" href="#output-files" aria-label="Permalink to “Output files”">​</a></h3><p>A program edits its input files in place. <code>transcribe</code> writes a new file, <code>transcript.tex</code> unless the instruction names another.</p><h2 id="file-path-handling" tabindex="-1">File path handling <a class="header-anchor" href="#file-path-handling" aria-label="Permalink to “File path handling”">​</a></h2><p>TeXRA handles file paths as follows:</p><h3 id="relative-vs-absolute-paths" tabindex="-1">Relative vs. absolute paths <a class="header-anchor" href="#relative-vs-absolute-paths" aria-label="Permalink to “Relative vs. absolute paths”">​</a></h3><ul><li><strong>Display</strong>: Files are displayed with paths relative to the workspace root</li><li><strong>Processing</strong>: TeXRA resolves paths to their absolute form when needed</li><li><strong>Output</strong>: A task writes its changes to the files in your project.</li></ul><h3 id="file-discovery-rules" tabindex="-1">File discovery rules <a class="header-anchor" href="#file-discovery-rules" aria-label="Permalink to “File discovery rules”">​</a></h3><p>TeXRA uses built-in file extensions and exclusions when discovering inputs, context, edited files, and media. Read the <a href="./configuration.html#file-discovery">file discovery section of the configuration guide</a>.</p><h2 id="run-storage" tabindex="-1">Run storage <a class="header-anchor" href="#run-storage" aria-label="Permalink to “Run storage”">​</a></h2><p>Every run gets a run folder under TeXRA&#39;s workspace storage directory:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>executions/&lt;executionId&gt;/</span></span></code></pre></div><p>It holds the run&#39;s own files: pasted images, tool-edit previews and, when <code>texra.debug.saveModelIO</code> is enabled, debug JSON files. Use</p>`,16),a(m,{library:`texra`,name:`folder-open`}),c[26]||=t(` <strong>Open task folder</strong><p>in the Tasks view to inspect it, and <code>texra history show &lt;id&gt;</code> in the terminal. The documents a task edits stay in your project.</p><h2 id="working-with-latex-projects" tabindex="-1">Working with LaTeX projects <a class="header-anchor" href="#working-with-latex-projects" aria-label="Permalink to “Working with LaTeX projects”">​</a></h2><p>For LaTeX projects with many files and dependencies:</p><h3 id="latex-directory-structure" tabindex="-1">LaTeX directory structure <a class="header-anchor" href="#latex-directory-structure" aria-label="Permalink to “LaTeX directory structure”">​</a></h3><p>TeXRA works well with standard LaTeX project structures:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>project/</span></span>
<span class="line"><span>├── main.tex            # Main document</span></span>
<span class="line"><span>├── chapters/           # Chapter files</span></span>
<span class="line"><span>│   ├── intro.tex       # Introduction</span></span>
<span class="line"><span>│   └── methodology.tex # Methodology</span></span>
<span class="line"><span>├── figures/            # Figure directory</span></span>
<span class="line"><span>│   ├── diagram.pdf     # Figure file</span></span>
<span class="line"><span>│   └── graph.png       # Another figure</span></span>
<span class="line"><span>└── bibliography.bib    # Bibliography</span></span></code></pre></div><h3 id="latex-workshop-integration" tabindex="-1">LaTeX Workshop integration <a class="header-anchor" href="#latex-workshop-integration" aria-label="Permalink to “LaTeX Workshop integration”">​</a></h3><p>If a LaTeX workspace does not have the <a href="https://marketplace.visualstudio.com/items?itemName=James-Yu.latex-workshop" target="_blank" rel="noreferrer">LaTeX Workshop</a> extension installed, TeXRA offers to install it. TeXRA does not rewrite editor or LaTeX Workshop preferences during startup. Use TeXRA&#39;s LaTeX settings page to inspect and apply the available workspace recommendations explicitly.</p><h2 id="cross-computer-syncing" tabindex="-1">Cross-computer syncing <a class="header-anchor" href="#cross-computer-syncing" aria-label="Permalink to “Cross-computer syncing”">​</a></h2><p>If you work on several computers, you can sync the <strong>History</strong> folder (which holds packed document versions) via a cloud storage folder using a symlink:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/Dropbox/texra-projects/ProjectName/History</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/local/ProjectName/History</span></span></code></pre></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next steps”">​</a></h2><ul><li><a href="/guide/research-tools.html">Research tools</a>: how TeXRA uses external tools</li><li><a href="/guide/latex-diff.html">LaTeX Diff</a>: how to compare document versions</li></ul>`,15)])}var d=r(l,[[`render`,u]]);export{c as __pageData,d as default};